GIT_SSH_COMMAND=/usr/bin/false npm ci --no-audit --no-fund 2>&1 | grep -v 'npm warn deprecated' | tail -6 && \
ls node_modules/pokemon-showdown/dist/sim/index.js && \
node -e '
const {Dex}=require("pokemon-showdown");
const d=Dex.mod("champions");
for (const n of ["Rillaboom","Salamence-Mega","Indeedee-F","Urshifu-Rapid-Strike","Calyrex-Shadow"]) { const s=d.species.get(n); console.log(n,"->",s.exists,s.id,JSON.stringify(s.baseStats)); }
const f=Dex.formats.get("gen9championsvgc2026regmcbo3"); console.log("format exists:",f.exists, f.exists?f.ruleset:"");
' && npm run typecheck && node bin/vgc-usage-stats.js generate; echo "exit=$?"

